package com.gestourant.catalog;
import jakarta.validation.Valid; import jakarta.validation.constraints.*; import org.springframework.http.HttpStatus; import org.springframework.web.bind.annotation.*; import java.math.BigDecimal; import java.util.List;
@RestController @RequestMapping("/api/products") public class ProductController { private final ProductRepository products; public ProductController(ProductRepository p){products=p;} @GetMapping public List<Product> list(){return products.findAll();} @PostMapping @org.springframework.security.access.prepost.PreAuthorize("hasRole('ADMINISTRADOR')") @ResponseStatus(HttpStatus.CREATED) public Product create(@Valid @RequestBody ProductRequest r){return products.save(new Product(r.name(),r.description(),r.price(),r.stock()));} @PutMapping("/{id}") @org.springframework.security.access.prepost.PreAuthorize("hasRole('ADMINISTRADOR')") public Product update(@PathVariable Long id,@Valid @RequestBody ProductRequest r){Product p=products.findById(id).orElseThrow(()->new IllegalArgumentException("Producto no encontrado"));p.update(r.name(),r.description(),r.price(),r.stock(),r.active());return products.save(p);}@DeleteMapping("/{id}") @org.springframework.security.access.prepost.PreAuthorize("hasRole('ADMINISTRADOR')") @ResponseStatus(HttpStatus.NO_CONTENT) public void delete(@PathVariable Long id){products.delete(products.findById(id).orElseThrow(()->new IllegalArgumentException("Producto no encontrado")));} public record ProductRequest(@NotBlank @Size(max=120) String name,@NotBlank @Size(max=500) String description,@NotNull @DecimalMin("0.01") BigDecimal price,@NotNull @Min(0) Integer stock,boolean active){} }
